    ('SIS-E21', 'S51', 'Jueves', '18:00', '20:15')
  ) as x(materia_codigo, comision_codigo, dia, hora_inicio, hora_fin)
  join materias m on m.carrera_id = v_carrera_id and m.codigo = x.materia_codigo
  join comisiones c on c.materia_id = m.id and c.codigo = x.comision_codigo;

end $$;

