-- ── utn-industrial-2008 ──
do $$
declare
  v_carrera_id uuid;
begin
  select id into v_carrera_id from carreras where slug = 'utn-industrial-2008';

  insert into materias (carrera_id, codigo, numero, nombre, nivel, carga_horaria, duracion, es_electiva, es_placeholder_electiva, horas_anuales_electiva, horas_anuales_requeridas, es_seminario, fuera_de_plan, solo_ingenieria) values
    (v_carrera_id, 'UTN-AM1', null, 'Análisis Matemático I', 1, null, null, false, false, null, null, false, false, false),
    (v_carrera_id, 'UTN-QG', null, 'Química General', 1, null, null, false, false, null, null, false, false, false),
    (v_carrera_id, 'UTN-SDR', null, 'Sistemas de Representación', 1, null, null, false, false, null, null, false, false, false),
